export enum Subject {
  ARITHMETIC = 'Arithmetic',
  REASONING = 'Reasoning'
}

export enum Difficulty {
  EASY = 'Easy',
  MEDIUM = 'Medium',
  HARD = 'Hard'
}

export interface Question {
  id: number;
  text: string;
  options: string[];
  correctAnswerIndex: number;
  explanation: string;
  topic?: string;
  figureSVG?: string; // Optional field for non-verbal reasoning images
}

export interface QuizConfig {
  subject: Subject;
  difficulty: Difficulty;
  questionCount: number;
  timeLimitMinutes: number; 
}

export interface QuizState {
  currentQuestionIndex: number;
  answers: Record<number, number>; // questionId -> selectedOptionIndex
  questionTimes: Record<number, number>; // questionId -> seconds taken
  isFinished: boolean;
  score: number;
  totalTimeTaken: number;
  startTime: number;
}

export interface ExamResult {
  id: string;
  date: string; // ISO string
  subject: Subject;
  difficulty: Difficulty;
  score: number;
  totalQuestions: number;
  accuracy: number;
  timeTaken: number;
  answers: Record<number, number>; // Store strictly essential data
}

import React, { useEffect, useState } from 'react';
import { Subject, Difficulty, QuizConfig } from '../types';
import { BookOpen, Brain, Play, BarChart2, ShieldCheck, Crown } from 'lucide-react';
import { getTotalAttempts } from '../services/storageService';

interface WelcomeScreenProps {
  onStart: (config: QuizConfig) => void;
  onViewAnalytics: () => void;
  isLoading: boolean;
}

const WelcomeScreen: React.FC<WelcomeScreenProps> = ({ onStart, onViewAnalytics, isLoading }) => {
  const [subject, setSubject] = useState<Subject>(Subject.ARITHMETIC);
  const [difficulty, setDifficulty] = useState<Difficulty>(Difficulty.EASY);

  useEffect(() => {
    // Adaptive Difficulty Rule: 
    // < 50 attempts = Easy
    // 50 - 120 attempts = Medium
    // > 120 attempts = Hard
    const totalAttempts = getTotalAttempts();
    if (totalAttempts > 120) {
      setDifficulty(Difficulty.HARD);
    } else if (totalAttempts > 50) {
      setDifficulty(Difficulty.MEDIUM);
    } else {
      setDifficulty(Difficulty.EASY);
    }
  }, []);

  const getQuestionCount = (subj: Subject) => (subj === Subject.ARITHMETIC ? 12 : 25);

  // 30 seconds per question rule
  const getTimeLimit = (subj: Subject) => {
    const count = getQuestionCount(subj);
    return (count * 30) / 60; // Minutes
  };

  const handleStart = () => {
    onStart({
      subject,
      difficulty,
      questionCount: getQuestionCount(subject),
      timeLimitMinutes: getTimeLimit(subject)
    });
  };

  return (
    <div className="max-w-5xl mx-auto p-6 animate-fade-in text-zinc-100">
      <div className="text-center mb-16 pt-10">
        <div className="inline-flex items-center justify-center p-3 mb-6 bg-amber-500/10 rounded-2xl border border-amber-500/20">
          <Crown className="text-amber-500 w-8 h-8 mr-2" />
          <span className="text-amber-500 font-bold tracking-widest text-sm uppercase">Official Prep Partner</span>
        </div>
        <h1 className="text-5xl md:text-7xl font-bold mb-6 tracking-tight font-space">
          Shubham <span className="text-transparent bg-clip-text bg-gradient-to-r from-amber-400 to-amber-600">AptiMaster</span>
        </h1>
        <p className="text-zinc-400 text-lg md:text-xl max-w-2xl mx-auto font-light">
          Shubham's Elite Aptitude Test Application. <br/>
          <span className="text-zinc-500 text-sm mt-2 block">Premium SSC • Banking • Railways • UPSC CSAT Preparation</span>
        </p>
      </div>

      <div className="grid md:grid-cols-2 gap-6 mb-12">
        {/* Arithmetic Card */}
        <div 
          onClick={() => setSubject(Subject.ARITHMETIC)}
          className={`cursor-pointer group relative p-8 rounded-3xl border transition-all duration-300 ${
            subject === Subject.ARITHMETIC 
              ? 'border-amber-500/50 bg-zinc-900 shadow-[0_0_30px_rgba(245,158,11,0.15)]' 
              : 'border-zinc-800 bg-zinc-900/50 hover:border-zinc-700'
          }`}
        >
          <div className="flex justify-between items-start mb-6">
            <div className={`p-4 rounded-2xl ${subject === Subject.ARITHMETIC ? 'bg-amber-500 text-black' : 'bg-zinc-800 text-zinc-400'}`}>
              <BookOpen size={28} />
            </div>
            {subject === Subject.ARITHMETIC && <div className="text-amber-500 font-bold text-sm bg-amber-500/10 px-3 py-1 rounded-full border border-amber-500/20">SELECTED</div>}
          </div>
          <h3 className="text-2xl font-bold mb-2">Arithmetic</h3>
          <p className="text-zinc-400 text-sm mb-6 leading-relaxed">
            12 Targeted Questions. Percentage, Ratio, Profit/Loss, Time & Work, DI. 
            <br/><span className="text-amber-500/80 text-xs mt-2 block">Strict 30s/Question Pace</span>
          </p>
          <div className="flex gap-2 text-xs font-mono text-zinc-500">
            <span className="bg-zinc-800 px-2 py-1 rounded">12 Qs</span>
            <span className="bg-zinc-800 px-2 py-1 rounded">6 Mins</span>
          </div>
        </div>

        {/* Reasoning Card */}
        <div 
          onClick={() => setSubject(Subject.REASONING)}
          className={`cursor-pointer group relative p-8 rounded-3xl border transition-all duration-300 ${
            subject === Subject.REASONING 
              ? 'border-emerald-500/50 bg-zinc-900 shadow-[0_0_30px_rgba(16,185,129,0.15)]' 
              : 'border-zinc-800 bg-zinc-900/50 hover:border-zinc-700'
          }`}
        >
          <div className="flex justify-between items-start mb-6">
            <div className={`p-4 rounded-2xl ${subject === Subject.REASONING ? 'bg-emerald-500 text-black' : 'bg-zinc-800 text-zinc-400'}`}>
              <Brain size={28} />
            </div>
            {subject === Subject.REASONING && <div className="text-emerald-500 font-bold text-sm bg-emerald-500/10 px-3 py-1 rounded-full border border-emerald-500/20">SELECTED</div>}
          </div>
          <h3 className="text-2xl font-bold mb-2">Reasoning</h3>
          <p className="text-zinc-400 text-sm mb-6 leading-relaxed">
            25 Mixed Questions. Verbal & Non-Verbal. Syllogisms, Series, Coding.
            <br/><span className="text-emerald-500/80 text-xs mt-2 block">Strict 30s/Question Pace</span>
          </p>
          <div className="flex gap-2 text-xs font-mono text-zinc-500">
            <span className="bg-zinc-800 px-2 py-1 rounded">25 Qs</span>
            <span className="bg-zinc-800 px-2 py-1 rounded">12.5 Mins</span>
          </div>
        </div>
      </div>

      {/* Action Bar */}
      <div className="bg-zinc-900/80 backdrop-blur-sm border border-zinc-800 p-6 rounded-3xl flex flex-col md:flex-row items-center justify-between gap-6">
        <div className="flex items-center gap-4">
           <div className="p-3 bg-zinc-800 rounded-xl text-zinc-400">
             <ShieldCheck size={24} />
           </div>
           <div>
             <div className="text-sm text-zinc-400 uppercase tracking-wider font-bold">Current Level</div>
             <div className="text-xl font-bold text-white">{difficulty} <span className="text-xs text-zinc-500 font-normal">(Auto-set based on history)</span></div>
           </div>
        </div>

        <div className="flex gap-4 w-full md:w-auto">
          <button
            onClick={onViewAnalytics}
            className="flex-1 md:flex-none flex items-center justify-center gap-2 px-6 py-4 bg-zinc-800 hover:bg-zinc-700 text-zinc-200 font-bold rounded-xl transition-all border border-zinc-700 hover:border-zinc-600"
          >
            <BarChart2 size={20} /> Analytics
          </button>

          <button
            onClick={handleStart}
            disabled={isLoading}
            className={`flex-1 md:flex-none flex items-center justify-center gap-2 px-8 py-4 bg-gradient-to-r from-amber-500 to-orange-600 hover:from-amber-400 hover:to-orange-500 text-black font-bold rounded-xl transition-all shadow-lg shadow-amber-900/20 transform active:scale-95 ${
              isLoading ? 'opacity-70 cursor-wait' : ''
            }`}
          >
            {isLoading ? (
              <>Constructing Exam...</>
            ) : (
              <>
                Start Exam <Play size={20} fill="currentColor" />
              </>
            )}
          </button>
        </div>
      </div>
    </div>
  );
};

export default WelcomeScreen;

import React, { useEffect, useState } from 'react';
import { Question, QuizState, Subject } from '../types';
import { Clock, ChevronRight, AlertTriangle, Timer, Lightbulb, Unlock } from 'lucide-react';

interface QuizScreenProps {
  questions: Question[];
  timeLimitMinutes: number;
  onFinish: (state: QuizState) => void;
  subject: Subject;
}

const QuizScreen: React.FC<QuizScreenProps> = ({ questions, timeLimitMinutes, onFinish, subject }) => {
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);
  const [answers, setAnswers] = useState<Record<number, number>>({});
  const [questionTimes, setQuestionTimes] = useState<Record<number, number>>({});

  // Total Exam Timer (Counts Down, goes negative for overtime)
  const [totalTimeRemaining, setTotalTimeRemaining] = useState(timeLimitMinutes * 60);

  // Current Question Timer (Counts Up to track 30s target)
  const [currentQTimer, setCurrentQTimer] = useState(0);

  // Auto-reveal solution state
  const [isTimeLimitBreached, setIsTimeLimitBreached] = useState(false);

  const [startTime] = useState(Date.now());
  const [isSubmitConfirmOpen, setIsSubmitConfirmOpen] = useState(false);

  const currentQuestion = questions[currentQuestionIndex];

  // Global Timer - Continues into negative
  useEffect(() => {
    const timer = setInterval(() => {
      setTotalTimeRemaining((prev) => prev - 1);
    }, 1000);
    return () => clearInterval(timer);
  }, []);

  // Question Timer Reset on change
  useEffect(() => {
    setCurrentQTimer(0);
    setIsTimeLimitBreached(false); // Reset auto-reveal on new question
    const qTimer = setInterval(() => {
      setCurrentQTimer(t => t + 1);
    }, 1000);
    return () => clearInterval(qTimer);
  }, [currentQuestionIndex]);

  // Logic: Arithmetic Auto-Reveal after 60 seconds
  useEffect(() => {
    if (
      subject === Subject.ARITHMETIC && 
      currentQTimer >= 60 && 
      !isTimeLimitBreached && 
      answers[currentQuestion.id] === undefined
    ) {
      setIsTimeLimitBreached(true);
    }
  }, [currentQTimer, subject, isTimeLimitBreached, answers, currentQuestion.id]);

  // Track time when moving away
  const saveCurrentQTime = () => {
    setQuestionTimes(prev => ({
      ...prev,
      [currentQuestion.id]: (prev[currentQuestion.id] || 0) + currentQTimer
    }));
  };

  const handleFinish = () => {
    saveCurrentQTime();
    let score = 0;
    questions.forEach(q => {
      if (answers[q.id] === q.correctAnswerIndex) {
        score++;
      }
    });

    onFinish({
      currentQuestionIndex,
      answers,
      questionTimes: { ...questionTimes, [currentQuestion.id]: currentQTimer },
      isFinished: true,
      score,
      totalTimeTaken: (timeLimitMinutes * 60) - totalTimeRemaining, // Handles negative remainder correctly
      startTime
    });
  };

  const handleOptionSelect = (optionIndex: number) => {
    setAnswers(prev => ({
      ...prev,
      [currentQuestion.id]: optionIndex
    }));
  };

  const handleNext = () => {
    saveCurrentQTime();
    if (currentQuestionIndex < questions.length - 1) {
      setCurrentQuestionIndex(prev => prev + 1);
    } else {
      setIsSubmitConfirmOpen(true);
    }
  };

  // Improved format to handle negative time (Overtime)
  const formatTime = (seconds: number) => {
    const isNegative = seconds < 0;
    const absSeconds = Math.abs(seconds);
    const m = Math.floor(absSeconds / 60);
    const s = absSeconds % 60;
    return `${isNegative ? '-' : ''}${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}`;
  };

  const answeredCount = Object.keys(answers).length;
  const progressPercent = ((currentQuestionIndex + 1) / questions.length) * 100;

  // Negative Time Logic: If > 30s, we show negative time visually
  const isOverTime = currentQTimer > 30;
  const negativeTime = currentQTimer - 30;

  const isGlobalOvertime = totalTimeRemaining < 0;

  return (
    <div className="max-w-6xl mx-auto p-4 md:p-6 min-h-screen flex flex-col font-inter text-zinc-100">
      {/* Header */}
      <div className="flex flex-col md:flex-row md:items-center justify-between bg-zinc-900 p-4 rounded-2xl border border-zinc-800 mb-6 gap-4">
        <div>
          <h2 className="text-xl font-bold font-space text-white">Shubham AptiMaster <span className="text-amber-500 text-sm font-normal ml-2">Live Exam</span></h2>
          <div className="text-sm text-zinc-500 mt-1">Topic: {currentQuestion.topic || 'General'}</div>
        </div>

        <div className="flex gap-4">
           {/* Per Question Timer */}
           <div className={`flex items-center gap-2 px-4 py-2 rounded-lg border ${isOverTime ? 'bg-red-900/20 border-red-500/50 text-red-400' : 'bg-zinc-800 border-zinc-700 text-zinc-300'}`}>
             <Timer size={18} />
             <span className="font-mono font-bold">
               {isOverTime ? `-${formatTime(negativeTime)}` : formatTime(currentQTimer)}
             </span>
             <span className="text-xs opacity-60">/ 00:30</span>
           </div>

           {/* Total Timer */}
           <div className={`flex items-center gap-2 px-4 py-2 rounded-lg border ${isGlobalOvertime ? 'bg-red-600 border-red-500 text-white animate-pulse' : totalTimeRemaining < 60 ? 'bg-orange-500/20 text-orange-400 border-orange-500/50' : 'bg-zinc-800 border-zinc-700 text-amber-500'}`}>
             <Clock size={18} />
             <span className="font-mono font-bold">
               {isGlobalOvertime && "OVERTIME: "}{formatTime(totalTimeRemaining)}
             </span>
           </div>
        </div>
      </div>

      <div className="flex-1 flex flex-col gap-6">
        {/* Progress */}
        <div className="w-full bg-zinc-900 h-1 rounded-full overflow-hidden">
          <div className="h-full bg-amber-500 transition-all duration-300" style={{ width: `${progressPercent}%` }}></div>
        </div>

        {/* Question Card */}
        <div className="flex-1 bg-zinc-900 rounded-3xl border border-zinc-800 p-6 md:p-10 shadow-2xl shadow-black/50 flex flex-col">
          <div className="flex justify-between items-start mb-6">
             <span className="text-zinc-500 font-mono text-sm">Q.{currentQuestionIndex + 1}</span>
             {answers[currentQuestion.id] !== undefined && <span className="text-emerald-500 text-xs font-bold uppercase tracking-wider bg-emerald-500/10 px-2 py-1 rounded">Answered</span>}
          </div>

          <h3 className="text-xl md:text-2xl font-medium text-zinc-100 leading-relaxed mb-6 font-space">
            {currentQuestion.text}
          </h3>

          {/* Render SVG Figure if available */}
          {currentQuestion.figureSVG && (
            <div className="mb-8 p-4 bg-zinc-800/50 rounded-xl border border-zinc-700 flex justify-center">
              <div 
                className="w-full max-w-2xl text-zinc-200 [&>svg]:w-full [&>svg]:h-auto [&>svg]:max-h-[300px]"
                dangerouslySetInnerHTML={{ __html: currentQuestion.figureSVG }}
              />
            </div>
          )}

          <div className="grid md:grid-cols-2 gap-4">
            {currentQuestion.options.map((option, idx) => {
              // Logic to visually highlight the correct answer if time limit breached for Arithmetic
              const isCorrectAndRevealed = isTimeLimitBreached && idx === currentQuestion.correctAnswerIndex;
              const isSelected = answers[currentQuestion.id] === idx;

              return (
                <button
                  key={idx}
                  onClick={() => handleOptionSelect(idx)}
                  className={`text-left p-5 rounded-xl border transition-all flex items-center gap-4 group ${
                    isSelected
                      ? 'border-amber-500 bg-amber-500/10 text-amber-100'
                      : isCorrectAndRevealed
                        ? 'border-emerald-500 bg-emerald-900/20 text-emerald-100' // Highlight revealed answer
                        : 'border-zinc-800 bg-zinc-900/50 text-zinc-400 hover:border-zinc-600 hover:bg-zinc-800'
                  }`}
                >
                  <div className={`w-8 h-8 rounded-lg flex items-center justify-center text-sm font-bold transition-colors ${
                    isSelected 
                      ? 'bg-amber-500 text-black' 
                      : isCorrectAndRevealed
                        ? 'bg-emerald-500 text-black'
                        : 'bg-zinc-800 text-zinc-500 group-hover:bg-zinc-700'
                  }`}>
                    {String.fromCharCode(65 + idx)}
                  </div>
                  <span className="text-lg">{option}</span>
                </button>
              );
            })}
          </div>

          {/* Solution Auto-Reveal Section */}
          {isTimeLimitBreached && (
            <div className="mt-8 p-6 bg-indigo-950/30 border border-indigo-500/30 rounded-2xl animate-fade-in relative overflow-hidden">
               <div className="absolute top-0 left-0 w-1 h-full bg-indigo-500"></div>
               <div className="flex items-center gap-3 text-indigo-400 font-bold mb-3 uppercase tracking-wider text-sm">
                 <Unlock size={18} />
                 <span>Time Limit (60s) Exceeded — Solution Revealed</span>
               </div>
               <div className="flex items-start gap-3">
                 <Lightbulb className="flex-shrink-0 text-amber-400 mt-1" size={20} />
                 <p className="text-zinc-300 leading-relaxed whitespace-pre-wrap">
                   {currentQuestion.explanation}
                 </p>
               </div>
            </div>
          )}

          <div className="mt-auto pt-8 flex justify-end">
            <button
              onClick={handleNext}
              className="flex items-center gap-2 px-8 py-4 rounded-xl font-bold text-black bg-white hover:bg-zinc-200 transition-colors shadow-lg shadow-white/5"
            >
              {currentQuestionIndex === questions.length - 1 ? 'Finish Exam' : 'Next Question'} <ChevronRight size={20} />
            </button>
          </div>
        </div>
      </div>

      {/* Confirmation Modal */}
      {isSubmitConfirmOpen && (
        <div className="fixed inset-0 bg-black/80 backdrop-blur-md flex items-center justify-center z-50 p-4">
          <div className="bg-zinc-900 border border-zinc-800 rounded-3xl p-8 max-w-md w-full">
            <div className="flex items-center gap-3 text-amber-500 mb-4">
              <AlertTriangle size={32} />
              <h3 className="text-2xl font-bold font-space text-white">Submit Exam?</h3>
            </div>
            <p className="text-zinc-400 mb-8 leading-relaxed">
              You have answered <strong className="text-white">{answeredCount}</strong> out of <strong className="text-white">{questions.length}</strong> questions.
              <br/>
              Unanswered questions will be marked as skipped.
            </p>
            <div className="flex gap-4">
              <button
                onClick={() => setIsSubmitConfirmOpen(false)}
                className="flex-1 px-6 py-3 rounded-xl border border-zinc-700 font-bold text-zinc-300 hover:bg-zinc-800"
              >
                Review
              </button>
              <button
                onClick={handleFinish}
                className="flex-1 px-6 py-3 rounded-xl bg-amber-500 text-black font-bold hover:bg-amber-400"
              >
                Submit Now
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default QuizScreen;

import { GoogleGenAI, Type, Schema } from "@google/genai";
import { Subject, Difficulty, Question } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const generateQuestions = async (
  subject: Subject,
  difficulty: Difficulty,
  count: number // Arithmetic: 12, Reasoning: 25
): Promise<Question[]> => {
  const modelName = "gemini-3-flash-preview";

  let prompt = "";

  if (subject === Subject.ARITHMETIC) {
    prompt = `
      You are 'Shubham AptiMaster', a strict examiner for top-tier Indian Government Competitive Exams (SSC CGL, IBPS PO, UPSC CSAT).
      Generate exactly ${count} (12) unique, high-quality Arithmetic questions.
      Difficulty: ${difficulty}.

      MANDATORY TOPIC DISTRIBUTION (Exactly 1 Question from each of the following 11 topics, fill the 12th question with a high-weightage topic like DI or Simplification):
      1. Percentage
      2. Average
      3. Ratio & Proportion
      4. Partnership
      5. Profit and Loss
      6. Unitary Method
      7. Time and Work
      8. Time and Distance
      9. Simplification
      10. Data Interpretation (Create a text-based Caselet or simple tabular data in the question text).
      11. Unit (Focus on Units Digit, Digit Sum, or Number System Unit Basics).

      Context: Questions must be conceptually tricky but solvable within 30-45 seconds using shortcuts.
      Do not use complex LaTeX. Use plain text.
    `;
  } else {
    prompt = `
      You are 'Shubham AptiMaster', a strict examiner for Indian Government Exams.
      Generate exactly ${count} (25) unique Reasoning questions.
      Difficulty: ${difficulty}.

      MANDATORY RULES:
      1. **Topic Mix**: Include both Verbal (Syllogism, Blood Relations, Coding-Decoding) and **Non-Verbal** (Series, Analogies, Odd One Out, Mirror Images).
      2. **Non-Verbal Questions (Important)**: For at least 5-8 questions (Series, Figure Counting, Mirror Images), you MUST provide a visual representation. 
         - Since you are a text AI, you must generate a **clean, simple SVG code string** in the 'figureSVG' field.
         - The SVG should draw the 'Problem Figures' and the 'Answer Figures' (labeled A, B, C, D) inside one canvas.
         - Use white or light-colored strokes (stroke="currentColor" or stroke="#e4e4e7") suitable for a dark background.
         - If a question has a figure, the 'options' array should simply be ["Figure A", "Figure B", "Figure C", "Figure D"].
      3. **Uniqueness**: Do not repeat logic consecutively.

      Context: Solvable within 30 seconds avg.
    `;
  }

  const questionSchema: Schema = {
    type: Type.ARRAY,
    items: {
      type: Type.OBJECT,
      properties: {
        id: { type: Type.INTEGER },
        topic: { type: Type.STRING, description: "The specific topic of the question" },
        text: { type: Type.STRING, description: "The question text. For non-verbal, say 'Study the figure below and select the correct option:'" },
        figureSVG: { 
          type: Type.STRING, 
          description: "Optional. A complete, valid <svg> string for non-verbal reasoning questions. Must include viewBox. Stroke colors should be light/white." 
        },
        options: { 
          type: Type.ARRAY, 
          items: { type: Type.STRING },
          description: "An array of 4 possible answers. For non-verbal, use ['A', 'B', 'C', 'D']"
        },
        correctAnswerIndex: { 
          type: Type.INTEGER, 
          description: "The index (0-3) of the correct answer" 
        },
        explanation: { 
          type: Type.STRING, 
          description: "Detailed step-by-step solution using short-cut methods suitable for exams." 
        }
      },
      required: ["id", "text", "options", "correctAnswerIndex", "explanation", "topic"]
    }
  };

  try {
    const response = await ai.models.generateContent({
      model: modelName,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: questionSchema,
        systemInstruction: "You are a competitive exam setter. Output raw JSON only. For non-verbal reasoning, ensure SVGs are valid and visible on dark backgrounds."
      }
    });

    const jsonText = response.text;
    if (!jsonText) throw new Error("No response from AI");

    const questions = JSON.parse(jsonText) as Question[];

    return questions.map((q, index) => ({
      ...q,
      id: index // Re-index to ensure safety
    }));

  } catch (error) {
    console.error("GenAI Error:", error);
    throw new Error("Exam generation failed. Please try again.");
  }
};

import React, { useEffect, useState } from 'react';
import { Subject, Difficulty, QuizConfig } from '../types';
import { BookOpen, Brain, Play, BarChart2, ShieldCheck, Crown } from 'lucide-react';
import { getTotalAttempts } from '../services/storageService';

interface WelcomeScreenProps {
  onStart: (config: QuizConfig) => void;
  onViewAnalytics: () => void;
  isLoading: boolean;
}

const WelcomeScreen: React.FC<WelcomeScreenProps> = ({ onStart, onViewAnalytics, isLoading }) => {
  const [subject, setSubject] = useState<Subject>(Subject.ARITHMETIC);
  const [difficulty, setDifficulty] = useState<Difficulty>(Difficulty.EASY);

  useEffect(() => {
    // Adaptive Difficulty Rule: 
    // < 50 attempts = Easy
    // 50 - 120 attempts = Medium
    // > 120 attempts = Hard
    const totalAttempts = getTotalAttempts();
    if (totalAttempts > 120) {
      setDifficulty(Difficulty.HARD);
    } else if (totalAttempts > 50) {
      setDifficulty(Difficulty.MEDIUM);
    } else {
      setDifficulty(Difficulty.EASY);
