            disabled={isLoading}
            className={`flex-1 lg:flex-none flex items-center justify-center gap-3 px-10 py-5 bg-gradient-to-br from-red-600 to-amber-600 hover:from-red-500 hover:to-amber-500 text-white font-bold rounded-2xl transition-all shadow-xl shadow-red-900/20 transform active:scale-95 group ${
              isLoading ? 'opacity-70 cursor-wait' : ''
            }`}
          >
            {isLoading ? (
              <span className="flex items-center gap-3">
                <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
                Constructing...
              </span>
            ) : (
              <>
                Mission Start <Play size={20} fill="currentColor" className="group-hover:translate-x-1 transition-transform" />
              </>
            )}
          </button>
        </div>
      </div>
    </div>
  );
};

