const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

// Systematic Topic List for Serieswise Rotation
const ARITHMETIC_TOPICS = [
  "Percentage", "Profit and Loss", "Interest (SI/CI)", "Ratio & Proportion", 
  "Average", "Ages", "Partnership", "Time and Work", "Time and Distance", 
  "Simplification", "LCM and HCF", "Unitary Method", "Mensuration (Area/Volume)", 
  "Data Interpretation", "Number System (Unit Digit)"
];

export const generateQuestions = async (
  subject: Subject,
  difficulty: Difficulty,
  count: number 
): Promise<Question[]> => {
  const modelName = "gemini-3-flash-preview";

  // Create a daily "Mission Seed" to ensure uniqueness every 24 hours
  const today = new Date();
  const dateString = today.toDateString();
  const dayOfYear = Math.floor((today.getTime() - new Date(today.getFullYear(), 0, 0).getTime()) / 86400000);

  // Calculate starting topic for "Serieswise" rotation based on day of year
  const startTopicIndex = dayOfYear % ARITHMETIC_TOPICS.length;
  const rotatedTopics = [
    ...ARITHMETIC_TOPICS.slice(startTopicIndex),
    ...ARITHMETIC_TOPICS.slice(0, startTopicIndex)
  ];

  let prompt = "";

  if (subject === Subject.ARITHMETIC) {
    prompt = `
      Today's Mission Context: ${dateString}. MISSION SEED: ${dayOfYear}.
      You are 'Shubham AptiMaster'. Generate ${count} (16) UNIQUE Arithmetic questions.

      SERIESWISE ROTATION RULE:
      Start your focus on these topics in order: ${rotatedTopics.join(", ")}.

      STRICT UNIQUENESS RULES:
      1. NEVER use standard textbook numbers (like 10%, 20%, or simple sums). Use complex, realistic competitive exam values.
      2. Create fresh scenarios (e.g., instead of 'A and B working', use specific professional roles or modern infrastructure projects).
      3. Focus on 'Shubham Shortcut' logic: the solution must be solvable in 30s using a trick described in the explanation.
      4. Ensure exactly one question from each of the rotated topics listed above.
    `;
  } else if (subject === Subject.REASONING) {
    prompt = `
      Mission Context: ${dateString}.
      Generate ${count} (25) Reasoning questions. Difficulty: ${difficulty}.
      Include 8 Non-Verbal questions with high-quality SVG figures.
      Focus on logic patterns that haven't been used in recent days. 
      Vary the coding-decoding logic and syllogism complexity.
    `;
  } else if (subject === Subject.THINKING) {
    prompt = `
      Mission Context: ${dateString}. 
      Generate 2 ELITE Cognitive Power questions.

      QUESTION 1 (Situation Mock): 
      Provide a complex administrative dilemma (e.g., Crisis Management or Ethical Choice in public office). 
      The user must analyze 4 possible actions.

      QUESTION 2 (Critical Thinking): 
      A complex logical argument or scientific hypothesis. The user must identify the hidden assumption or the fact that most weakens the argument.

      REQUIRED FOR BOTH:
      - 'strategyRules': 3 specific logical steps to decode this type of problem.
      - 'hints': 2 subtle nudges that encourage 'lateral thinking' without giving away the answer.
    `;
  }

  const questionSchema: Schema = {
    type: Type.ARRAY,
    items: {
      type: Type.OBJECT,
      properties: {
        id: { type: Type.INTEGER },
        topic: { type: Type.STRING },
        text: { type: Type.STRING },
        figureSVG: { type: Type.STRING },
        options: { type: Type.ARRAY, items: { type: Type.STRING } },
        correctAnswerIndex: { type: Type.INTEGER },
        explanation: { type: Type.STRING },
        hints: { type: Type.ARRAY, items: { type: Type.STRING } },
        strategyRules: { type: Type.ARRAY, items: { type: Type.STRING } }
      },
      required: ["id", "text", "options", "correctAnswerIndex", "explanation", "topic"]
    }
  };

  try {
    const response = await ai.models.generateContent({
      model: modelName,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: questionSchema,
        systemInstruction: `You are a world-class exam setter for the UPSC and SSC. 
        It is currently ${dateString}. Your goal is to ensure NO REPETITION from previous days. 
        Every question must be a 'New Challenge'. 
        For Arithmetic, prioritize conceptual clarity and shortcut-based solving.`
      }
    });

    const jsonText = response.text;
    if (!jsonText) throw new Error("No response from AI");

    const questions = JSON.parse(jsonText) as Question[];
    return questions.map((q, index) => ({ ...q, id: index }));
  } catch (error) {
    console.error("GenAI Error:", error);
    throw new Error("Failed to construct the Daily Mission. Please retry.");
  }
};

