interface AnalyticsScreenProps {
  onBack: () => void;
}

const AnalyticsScreen: React.FC<AnalyticsScreenProps> = ({ onBack }) => {
  const [history, setHistory] = useState<ExamResult[]>([]);
  const [loading, setLoading] = useState(true);
  const [filterSubject, setFilterSubject] = useState<Subject | 'ALL'>('ALL');

  useEffect(() => {
    const fetchHistory = async () => {
      const data = await getExamHistory();
      setHistory(data);
      setLoading(false);
    };
    fetchHistory();
  }, []);

  const filteredHistory = history.filter(h => filterSubject === 'ALL' || h.subject === filterSubject);

  const chartData = filteredHistory.map((h, i) => ({
    attempt: i + 1,
    date: new Date(h.date).toLocaleDateString(),
    score: Math.round((h.score / h.totalQuestions) * 100),
    accuracy: h.accuracy,
    subject: h.subject
  })).reverse();

  const overallAccuracy = chartData.length > 0 
    ? Math.round(chartData.reduce((acc, curr) => acc + curr.accuracy, 0) / chartData.length) 
    : 0;

  const subjectBreakdown = Object.values(Subject).map(subj => {
    const subjData = history.filter(h => h.subject === subj);
    return {
      name: subj,
      count: subjData.length,
      avgAcc: subjData.length > 0 
        ? Math.round(subjData.reduce((acc, curr) => acc + curr.accuracy, 0) / subjData.length) 
        : 0
    };
  });

  const handleDownloadPDF = () => {
    const element = document.getElementById('report-container');
    if (!element) return;

    const opt = {
      margin: 0.5,
      filename: `Shubham_AptiMaster_Report_${new Date().toISOString().split('T')[0]}.pdf`,
      image: { type: 'jpeg', quality: 0.98 },
      html2canvas: { scale: 2, useCORS: true, backgroundColor: '#ffffff' },
      jsPDF: { unit: 'in', format: 'letter', orientation: 'portrait' }
    };

    // Before generating, we temporarily apply print styles to the element
    const originalClass = element.className;
    element.classList.add('bg-white', 'text-black');

    // @ts-ignore
    window.html2pdf().set(opt).from(element).save().then(() => {
      element.className = originalClass;
    });
  };

  if (loading) {
    return (
      <div className="h-screen flex items-center justify-center">
        <div className="flex flex-col items-center gap-4">
          <Loader2 className="w-10 h-10 text-amber-500 animate-spin" />
          <p className="text-zinc-500 font-bold uppercase tracking-widest text-[10px]">Syncing Intelligence...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="max-w-7xl mx-auto p-6 min-h-screen text-zinc-100 pb-20">
      <div className="flex items-center justify-between mb-8 no-print">
        <button 
            onClick={onBack}
            className="flex items-center gap-2 text-zinc-400 hover:text-white transition-colors"
        >
            <ArrowLeft size={20} /> Back to Mission Control
        </button>
        <button 
            onClick={handleDownloadPDF}
            className="flex items-center gap-3 bg-amber-500 hover:bg-amber-400 text-black px-6 py-3 rounded-2xl font-bold shadow-lg shadow-amber-500/10 transition-all active:scale-95"
        >
