import React, { useState, useEffect } from 'react';
import WelcomeScreen from './components/WelcomeScreen';
import QuizScreen from './components/QuizScreen';
import ResultsScreen from './components/ResultsScreen';
import AnalyticsScreen from './components/AnalyticsScreen';
import LoginScreen from './components/LoginScreen';
import BrandLogo from './components/BrandLogo';
import { QuizConfig, Question, QuizState, Subject } from './types';
import { generateQuestions } from './services/geminiService';
import { getAttemptCount } from './services/storageService';
import { auth } from './firebase.ts';
import { onAuthStateChanged, signOut, User } from 'firebase/auth';
import { LogOut, User as UserIcon } from 'lucide-react';

const App: React.FC = () => {
  const [appState, setAppState] = useState<'login' | 'welcome' | 'quiz' | 'results' | 'analytics'>('login');
  const [user, setUser] = useState<User | null>(null);
  const [config, setConfig] = useState<QuizConfig | null>(null);
  const [questions, setQuestions] = useState<Question[]>([]);
  const [quizResultState, setQuizResultState] = useState<QuizState | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [authChecking, setAuthChecking] = useState(true);

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, (currentUser) => {
      setUser(currentUser);
      if (currentUser && appState === 'login') {
        setAppState('welcome');
      } else if (!currentUser) {
        setAppState('login');
      }
      setAuthChecking(false);
    });
    return () => unsubscribe();
  }, [appState]);

  const handleStartQuiz = async (newConfig: QuizConfig) => {
    setIsLoading(true);
    setError(null);
    setConfig(newConfig);

    try {
      // Corrected: Fetch the latest cross-device attempt count before generation
      const attemptCount = await getAttemptCount();

      const generatedQuestions = await generateQuestions(
        newConfig.subject,
        newConfig.difficulty,
        newConfig.questionCount,
        attemptCount
      );
      setQuestions(generatedQuestions);
      setAppState('quiz');
    } catch (err: any) {
      console.error(err);
      setError("Exam construction failed. Please verify API Connectivity.");
    } finally {
      setIsLoading(false);
    }
  };

  const handleFinishQuiz = (resultState: QuizState) => {
    setQuizResultState(resultState);
    setAppState('results');
  };

  const handleRestart = () => {
    setAppState('welcome');
    setConfig(null);
    setQuestions([]);
    setQuizResultState(null);
    setError(null);
  };

  const handleLogout = async () => {
    await signOut(auth);
    setAppState('login');
  };

  if (authChecking) {
    return (
      <div className="min-h-screen bg-zinc-950 flex items-center justify-center">
        <div className="flex flex-col items-center gap-6">
          <BrandLogo size={80} className="animate-pulse" />
          <div className="w-48 h-1 bg-zinc-900 rounded-full overflow-hidden">
             <div className="h-full bg-amber-500 animate-[loading_1.5s_infinite_ease-in-out]"></div>
          </div>
          <style>{`@keyframes loading { 0% { width: 0%; transform: translateX(-100%); } 50% { width: 100%; transform: translateX(0%); } 100% { width: 0%; transform: translateX(100%); } }`}</style>
        </div>
      </div>
    );
  }

  if (appState === 'login') {
    return <LoginScreen onLoginSuccess={() => setAppState('welcome')} />;
  }

  return (
    <div className="min-h-screen bg-zinc-950 font-inter selection:bg-amber-500 selection:text-black">
      {appState !== 'quiz' && (
        <nav className="bg-zinc-900/80 backdrop-blur-md border-b border-zinc-800 px-6 py-4 flex items-center justify-between sticky top-0 z-50 no-print">
          <div className="flex items-center gap-4 cursor-pointer group" onClick={handleRestart}>
            <BrandLogo size={44} className="group-hover:scale-110 transition-transform duration-300" />
            <div>
               <span className="font-bold text-xl tracking-tight text-white font-space">
                 Shubham <span className="text-amber-500">AptiMaster</span>
               </span>
               <div className="text-[10px] text-zinc-500 uppercase tracking-widest leading-none font-bold">Govt Exam Specialist</div>
            </div>
          </div>

          <div className="flex items-center gap-6">
            <div className="hidden md:flex items-center gap-3 px-4 py-2 bg-zinc-800 rounded-xl border border-zinc-700">
              <div className="w-8 h-8 rounded-lg bg-amber-500 flex items-center justify-center text-black">
                {user?.photoURL ? (
                  <img src={user.photoURL} alt="User" className="w-full h-full rounded-lg object-cover" />
                ) : (
                  <UserIcon size={16} />
                )}
              </div>
              <div className="text-left">
                <div className="text-xs font-bold text-white truncate max-w-[120px]">{user?.displayName || "Aspirant"}</div>
                <div className="text-[10px] text-zinc-500 font-mono">ID: {user?.uid.substring(0, 8)}</div>
              </div>
            </div>

            <button 
              onClick={handleLogout}
              className="p-3 bg-zinc-800 hover:bg-red-900/20 text-zinc-500 hover:text-red-500 rounded-xl border border-zinc-700 transition-all"
              title="Sign Out"
            >
              <LogOut size={20} />
            </button>
          </div>
        </nav>
      )}

      <main className="container mx-auto">
        {error && (
          <div className="max-w-md mx-auto mt-8 bg-red-900/20 border border-red-500/50 text-red-200 px-6 py-4 rounded-xl relative animate-bounce" role="alert">
            <strong className="font-bold">System Error: </strong>
            <span className="block sm:inline">{error}</span>
          </div>
        )}

        {appState === 'welcome' && (
          <WelcomeScreen 
            onStart={handleStartQuiz} 
            onViewAnalytics={() => setAppState('analytics')}
            isLoading={isLoading} 
          />
        )}

        {appState === 'analytics' && (
            <AnalyticsScreen onBack={() => setAppState('welcome')} />
        )}

        {appState === 'quiz' && config && (
          <QuizScreen 
            questions={questions} 
            timeLimitMinutes={config.timeLimitMinutes}
            onFinish={handleFinishQuiz}
            subject={config.subject}
          />
        )}

        {appState === 'results' && quizResultState && config && (
          <ResultsScreen 
            questions={questions}
            state={quizResultState}
            totalTimeMinutes={config.timeLimitMinutes}
            subject={config.subject}
            difficulty={config.difficulty}
            onRestart={handleRestart}
            onViewAnalytics={() => setAppState('analytics')}
          />
        )}
      </main>
    </div>
  );
};

export default App;

