import { db, auth } from "../firebase";
import { collection, addDoc, query, getDocs, orderBy, getCountFromServer } from "firebase/firestore";
import { ExamResult } from "../types";

const LOCAL_STORAGE_KEY = 'shubham_aptimaster_history';

export const saveExamResult = async (result: ExamResult): Promise<void> => {
  const user = auth.currentUser;

  try {
    const existing = getLocalHistory();
    existing.push(result);
    localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(existing));
  } catch (e) {
    console.error("Local save failed", e);
  }

  if (user) {
    try {
      await addDoc(collection(db, "users", user.uid, "attempts"), {
        ...result,
        userId: user.uid,
        createdAt: new Date().toISOString()
      });
    } catch (e) {
      console.error("Firestore save failed", e);
    }
  }
};

const getLocalHistory = (): ExamResult[] => {
  try {
    const data = localStorage.getItem(LOCAL_STORAGE_KEY);
    return data ? JSON.parse(data) : [];
  } catch (e) {
    return [];
  }
};

export const getExamHistory = async (): Promise<ExamResult[]> => {
  const user = auth.currentUser;

  if (!user) {
    return getLocalHistory();
  }

  try {
    const q = query(
      collection(db, "users", user.uid, "attempts"),
      orderBy("date", "desc")
    );
    const querySnapshot = await getDocs(q);
    const history: ExamResult[] = [];
    querySnapshot.forEach((doc) => {
      history.push(doc.data() as ExamResult);
    });
    return history.length > 0 ? history : getLocalHistory();
  } catch (e) {
    return getLocalHistory();
  }
};

export const getAttemptCount = async (): Promise<number> => {
  const user = auth.currentUser;
  if (!user) return getLocalHistory().length;

  try {
    const coll = collection(db, "users", user.uid, "attempts");
    const snapshot = await getCountFromServer(coll);
    const count = snapshot.data().count;
    return count > 0 ? count : getLocalHistory().length;
  } catch (e) {
    return getLocalHistory().length;
  }
};

export const getTotalAttempts = (): number => {
  return getLocalHistory().length;
};

