import { GoogleGenAI, Type } from "@google/genai";
import { Subject, Difficulty, Question } from "../types.ts";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const ARITHMETIC_TOPICS = [
  "Percentage", "Profit and Loss", "Interest (SI/CI)", "Ratio & Proportion", 
  "Average", "Ages", "Partnership", "Time and Work", "Time and Distance", 
  "Simplification", "LCM and HCF", "Unitary Method", "Mensuration (Area/Volume)", 
  "Data Interpretation", "Number System (Unit Digit)"
];

export const generateQuestions = async (
  subject: Subject,
  difficulty: Difficulty,
  count: number,
  attemptCount: number
): Promise<Question[]> => {
  const modelName = "gemini-3-flash-preview";
  const missionId = Math.random().toString(36).substring(7).toUpperCase();
  const startTopicIndex = attemptCount % ARITHMETIC_TOPICS.length;
  const rotatedTopics = [
    ...ARITHMETIC_TOPICS.slice(startTopicIndex),
    ...ARITHMETIC_TOPICS.slice(0, startTopicIndex)
  ];

  let prompt = "";
  if (subject === Subject.ARITHMETIC) {
    prompt = `MISSION_ID: ${missionId}. Subject: Arithmetic. Topics: ${rotatedTopics.join(", ")}. Difficulty: ${difficulty}. Count: ${count}. Ensure NO repetition.`;
  } else if (subject === Subject.REASONING) {
    prompt = `MISSION_ID: ${missionId}. Subject: Reasoning. Count: ${count}. Include SVGs for non-verbal questions.`;
  } else {
    prompt = `MISSION_ID: ${missionId}. Subject: Thinking. Elite scenarios.`;
  }

  const questionSchema = {
    type: Type.ARRAY,
    items: {
      type: Type.OBJECT,
      properties: {
        id: { type: Type.INTEGER },
        topic: { type: Type.STRING },
        text: { type: Type.STRING },
        figureSVG: { type: Type.STRING },
        options: { type: Type.ARRAY, items: { type: Type.STRING } },
        correctAnswerIndex: { type: Type.INTEGER },
        explanation: { type: Type.STRING },
        hints: { type: Type.ARRAY, items: { type: Type.STRING } },
        strategyRules: { type: Type.ARRAY, items: { type: Type.STRING } }
      },
      required: ["id", "text", "options", "correctAnswerIndex", "explanation", "topic"]
    }
  };

  try {
    const response = await ai.models.generateContent({
      model: modelName,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: questionSchema,
        systemInstruction: "You are Shubham AptiMaster. Generate a unique, never-before-seen exam mission."
      }
    });

    const jsonText = response.text;
    if (!jsonText) throw new Error("No response from AI");

    const questions = JSON.parse(jsonText) as Question[];
    return questions.map((q, index) => ({ ...q, id: index }));
  } catch (error) {
    console.error("GenAI Error:", error);
    throw new Error("Mission construction failed.");
  }
};

import { db, auth } from "../firebase.ts";
import { collection, addDoc, query, getDocs, orderBy, getCountFromServer } from "firebase/firestore";
import { ExamResult } from "../types.ts";

const LOCAL_STORAGE_KEY = 'shubham_aptimaster_history';

export const saveExamResult = async (result: ExamResult): Promise<void> => {
  const user = auth.currentUser;

  try {
    const data = localStorage.getItem(LOCAL_STORAGE_KEY);
    const existing = data ? JSON.parse(data) : [];
    existing.push(result);
    localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(existing));
  } catch (e) {
    console.error("Local save failed", e);
  }

  if (user) {
    try {
      await addDoc(collection(db, "users", user.uid, "attempts"), {
        ...result,
        userId: user.uid,
        createdAt: new Date().toISOString()
      });
    } catch (e) {
      console.error("Firestore save failed", e);
    }
  }
};

export const getExamHistory = async (): Promise<ExamResult[]> => {
  const user = auth.currentUser;
  const localData = localStorage.getItem(LOCAL_STORAGE_KEY);
  const localHistory = localData ? JSON.parse(localData) : [];

  if (!user) return localHistory;

  try {
    const q = query(
      collection(db, "users", user.uid, "attempts"),
      orderBy("date", "desc")
    );
    const querySnapshot = await getDocs(q);
    const history: ExamResult[] = [];
    querySnapshot.forEach((doc) => {
      history.push(doc.data() as ExamResult);
    });
    return history.length > 0 ? history : localHistory;
  } catch (e) {
    return localHistory;
  }
};

export const getAttemptCount = async (): Promise<number> => {
  const user = auth.currentUser;
  const localData = localStorage.getItem(LOCAL_STORAGE_KEY);
  const localCount = localData ? JSON.parse(localData).length : 0;

  if (!user) return localCount;

  try {
    const coll = collection(db, "users", user.uid, "attempts");
    const snapshot = await getCountFromServer(coll);
    const count = snapshot.data().count;
    return count > 0 ? count : localCount;
  } catch (e) {
    return localCount;
  }
};

