interface AnalyticsScreenProps {
  onBack: () => void;
}

const AnalyticsScreen: React.FC<AnalyticsScreenProps> = ({ onBack }) => {
  const [history, setHistory] = useState<ExamResult[]>([]);
  const [loading, setLoading] = useState(true);
  const [filterSubject, setFilterSubject] = useState<Subject | 'ALL'>('ALL');

  useEffect(() => {
    const fetchHistory = async () => {
      const data = await getExamHistory();
      setHistory(data);
      setLoading(false);
    };
    fetchHistory();
  }, []);

  const filteredHistory = history.filter(h => filterSubject === 'ALL' || h.subject === filterSubject);

  const chartData = filteredHistory.map((h, i) => ({
    attempt: i + 1,
    date: new Date(h.date).toLocaleDateString(),
    score: Math.round((h.score / h.totalQuestions) * 100),
    accuracy: h.accuracy,
    subject: h.subject
  })).reverse();

  const overallAccuracy = chartData.length > 0 
    ? Math.round(chartData.reduce((acc, curr) => acc + curr.accuracy, 0) / chartData.length) 
    : 0;

  const subjectBreakdown = Object.values(Subject).map(subj => {
    const subjData = history.filter(h => h.subject === subj);
    return {
      name: subj,
      count: subjData.length,
      avgAcc: subjData.length > 0 
        ? Math.round(subjData.reduce((acc, curr) => acc + curr.accuracy, 0) / subjData.length) 
        : 0
    };
  });

  const handleDownloadPDF = () => {
    const element = document.getElementById('report-container');
    if (!element) return;
    // @ts-ignore
    window.html2pdf().from(element).save();
  };

  if (loading) {
    return (
      <div className="h-screen flex items-center justify-center">
        <Loader2 className="w-10 h-10 text-amber-500 animate-spin" />
      </div>
    );
  }

  return (
    <div className="max-w-7xl mx-auto p-6 min-h-screen text-zinc-100 pb-20">
      <div className="flex items-center justify-between mb-8">
        <button onClick={onBack} className="flex items-center gap-2 text-zinc-400 hover:text-white transition-colors">
            <ArrowLeft size={20} /> Back
        </button>
        <button onClick={handleDownloadPDF} className="bg-amber-500 text-black px-6 py-3 rounded-2xl font-bold">
            <Download size={18} className="inline mr-2" /> Export PDF
        </button>
      </div>

      <div id="report-container" className="space-y-8">
        <h1 className="text-4xl font-bold font-space text-white">Cognitive Performance</h1>
        <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
          <div className="bg-zinc-900 border border-zinc-800 p-8 rounded-3xl">
              <div className="text-zinc-500 uppercase tracking-widest text-[10px]">Total Missions</div>
              <div className="text-4xl font-bold text-white font-space">{history.length}</div>
          </div>
          <div className="bg-zinc-900 border border-zinc-800 p-8 rounded-3xl">
              <div className="text-zinc-500 uppercase tracking-widest text-[10px]">Avg. Accuracy</div>
              <div className="text-4xl font-bold text-emerald-500 font-space">{overallAccuracy}%</div>
          </div>
        </div>
